          name: string;
          key_hash: string;
          permissions: string[];
          rate_limit: number;
          usage_count: number;
          last_used?: string;
          expires_at?: string;
          created_at: string;
          is_active: boolean;
        };
      };
    };
  };
}

// Subscription types
export type SubscriptionStatus = 
  | 'trialing'
  | 'active'
  | 'canceled'
  | 'incomplete'
  | 'incomplete_expired'
  | 'past_due'
  | 'unpaid';

export type SubscriptionTier = 
  | 'free'
  | 'starter'
  | 'professional'
  | 'enterprise';

export type Json = string | number | boolean | null | { [key: string]: Json | undefined } | Json[];

// Revenue types
export interface RevenueMetrics {
  daily: number;
  monthly: number;
  annual: number;
  mrr: number;
  arr: number;
  churnRate: number;
  ltv: number;
  cac: number;
  activeSubscriptions: number;
  totalUsers: number;
}

export interface PricingTier {
  id: SubscriptionTier;
  name: string;
  price: number;
  credits: number;
  features: string[];
  stripePriceId: string;
  popular?: boolean;
  description: string;
}

// API types
export interface APIResponse<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
}

export interface PaginatedResponse<T> extends APIResponse<T[]> {
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

// User types
export interface User {
  id: string;
  email: string;
  fullName?: string;
  avatarUrl?: string;
  subscriptionTier: SubscriptionTier;
  subscriptionStatus: SubscriptionStatus;
  credits: number;
  totalSpent: number;
  createdAt: string;
  lastActive: string;
}

// Analytics types
export interface AnalyticsEvent {
  userId?: string;
  action: string;
  category: string;
  label?: string;
  value?: number;
  metadata?: Record<string, any>;
  timestamp: Date;
}

export interface DashboardMetrics {
  revenue: RevenueMetrics;
  users: {
    total: number;
    new: number;
    active: number;
    churn: number;
  };
  subscriptions: {
    total: number;
    byTier: Record<SubscriptionTier, number>;
    churnRate: number;
  };
  usage: {
    totalCreditsUsed: number;
    averagePerUser: number;
    topActions: Array<{ action: string; count: number }>;
  };
}

// Integration types
export interface TermuxConfig {
  apiEndpoint: string;
  apiKey: string;
  features: string[];
  rateLimit: number;
}

export interface HuggingFaceConfig {
  modelId: string;
  apiKey: string;
  endpoint: string;
  parameters: Record<string, any>;
}

// Error types
export interface AppError extends Error {
  code: string;
  statusCode: number;
  isOperational: boolean;
}
"""

