# Create Stripe webhook handler
stripe_webhook = """import { NextApiRequest, NextApiResponse } from 'next';
import { buffer } from 'micro';
import Stripe from 'stripe';
import { stripe, constructWebhookEvent } from '@/lib/stripe';
import { supabaseAdmin } from '@/lib/supabase';

export const config = {
  api: {
    bodyParser: false,
  },
};

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const buf = await buffer(req);
  const sig = req.headers['stripe-signature'];

  let event: Stripe.Event;

  try {
    event = constructWebhookEvent(buf.toString(), sig as string);
  } catch (err: any) {
    console.error('Webhook signature verification failed:', err.message);
    return res.status(400).json({ error: 'Webhook signature verification failed' });
  }

  console.log('Received webhook event:', event.type);

  try {
    switch (event.type) {
      case 'customer.subscription.created':
      case 'customer.subscription.updated':
        await handleSubscriptionUpdate(event.data.object as Stripe.Subscription);
        break;

      case 'customer.subscription.deleted':
        await handleSubscriptionDeleted(event.data.object as Stripe.Subscription);
        break;

      case 'invoice.payment_succeeded':
        await handlePaymentSucceeded(event.data.object as Stripe.Invoice);
        break;

      case 'invoice.payment_failed':
        await handlePaymentFailed(event.data.object as Stripe.Invoice);
        break;

      case 'customer.created':
        await handleCustomerCreated(event.data.object as Stripe.Customer);
        break;

      default:
        console.log(`Unhandled event type: ${event.type}`);
    }

    res.status(200).json({ received: true });
  } catch (error) {
    console.error('Error processing webhook:', error);
    res.status(500).json({ error: 'Webhook processing failed' });
  }
}

async function handleSubscriptionUpdate(subscription: Stripe.Subscription) {
  const { customer, status, items, current_period_start, current_period_end } = subscription;

  // Get price information
  const priceId = items.data[0]?.price.id;
  let tier: string = 'starter';

  // Map price ID to tier (you'll need to set these based on your Stripe setup)
  if (priceId === process.env.STRIPE_PROFESSIONAL_PRICE_ID) {
    tier = 'professional';
  } else if (priceId === process.env.STRIPE_ENTERPRISE_PRICE_ID) {
    tier = 'enterprise';
  }

  // Update or create subscription record
  const { error: subError } = await supabaseAdmin
    .from('subscriptions')
    .upsert({
      id: subscription.id,
      user_id: null, // Will be updated by customer lookup
      status: status as any,
      tier: tier as any,
      price_id: priceId,
      quantity: items.data[0]?.quantity || 1,
      cancel_at_period_end: subscription.cancel_at_period_end,
      current_period_start: new Date(current_period_start * 1000).toISOString(),
      current_period_end: new Date(current_period_end * 1000).toISOString(),
      customer_id: customer as string,
      created: new Date(subscription.created * 1000).toISOString()
    });

  if (subError) {
    console.error('Error updating subscription:', subError);
  }

  // Update user record
  const { error: userError } = await supabaseAdmin
    .from('users')
    .update({
      subscription_id: subscription.id,
      subscription_status: status,
      subscription_tier: tier,
      credits: getCreditsForTier(tier)
    })
    .eq('stripe_customer_id', customer as string);

  if (userError) {
    console.error('Error updating user:', userError);
  }

  console.log(`Updated subscription ${subscription.id} to ${status}`);
}

async function handleSubscriptionDeleted(subscription: Stripe.Subscription) {
  const { customer } = subscription;

  // Update user to free tier
  const { error } = await supabaseAdmin
    .from('users')
    .update({
      subscription_id: null,
      subscription_status: 'canceled',
      subscription_tier: 'free',
      credits: 100 // Free tier credits
    })
    .eq('stripe_customer_id', customer as string);

  if (error) {
    console.error('Error handling subscription deletion:', error);
  }

  console.log(`Subscription ${subscription.id} deleted`);
}

async function handlePaymentSucceeded(invoice: Stripe.Invoice) {
  const { customer, amount_paid, subscription } = invoice;

  // Update total spent
  const { error } = await supabaseAdmin
    .rpc('increment_user_spending', {
      customer_id: customer as string,
      amount: amount_paid / 100 // Convert from cents
    });

  if (error) {
    console.error('Error updating user spending:', error);
  }

  // Track revenue
  await trackRevenue(amount_paid / 100);

  console.log(`Payment succeeded for ${customer}: $${amount_paid / 100}`);
}

async function handlePaymentFailed(invoice: Stripe.Invoice) {
  const { customer, subscription } = invoice;

  // Update subscription status
  if (subscription) {
    const { error } = await supabaseAdmin
      .from('users')
      .update({ 
        subscription_status: 'past_due' 
      })
      .eq('stripe_customer_id', customer as string);

    if (error) {
      console.error('Error updating payment failure:', error);
    }
  }

  console.log(`Payment failed for ${customer}`);
}

async function handleCustomerCreated(customer: Stripe.Customer) {
  // This might be handled during user registration instead
  console.log(`Customer created: ${customer.id}`);
}

async function trackRevenue(amount: number) {
  const today = new Date().toISOString().split('T')[0];

  // Update daily revenue
  const { error } = await supabaseAdmin
    .rpc('update_daily_revenue', {
      target_date: today,
      revenue_amount: amount
    });

  if (error) {
    console.error('Error tracking revenue:', error);
  }
}

function getCreditsForTier(tier: string): number {
  switch (tier) {
    case 'starter': return 1000;
    case 'professional': return 5000;
    case 'enterprise': return 20000;
    default: return 100; // free
  }
}
"""

